const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim();
let n = parseInt(input, 10);

let a = new Array(110).fill(0);
let i;

for (i = 1; ; i++) {
    if (n === 1) {
        break;
    }
    let yushu = n % 2;
    n = Math.floor(n / 2);
    a[i] = yushu;
    if (n === 1) {
        i++;
        break;
    }
}

let output = '';
output += i.toString();
i--;
for (; i >= 0; i--) {
    if (a[i]) {
        output += ' ' + i.toString();
    }
}
output += '\n';

process.stdout.write(output);

